        },
        {
            "@type": "WorkflowStep",
            "name": "Get Malicious Indicators",
            "description": null,
            "arguments": {
                "query": {
                    "sort": [],
                    "limit": 30,
                    "logic": "AND",
                    "filters": [
                        {
                            "type": "primitive",
                            "field": "alerts.uuid",
                            "value": "{{vars.alert_iri | basename}}",
                            "operator": "eq",
                            "_operator": "eq"
                        },
                        {
                            "logic": "OR",
                            "filters": [
                                {
                                    "type": "object",
                                    "field": "reputation",
                                    "value": "\/api\/3\/picklists\/50bfd06c-9aff-4f7d-b6d9-821339e31fe7",
                                    "_value": {
                                        "@id": "\/api\/3\/picklists\/50bfd06c-9aff-4f7d-b6d9-821339e31fe7",
                                        "itemValue": "Suspicious"
                                    },
                                    "operator": "eq"
