            "uuid": "e7b5395f-cc22-4c1f-b9a7-4419d7395051"
        },
        {
            "@type": "WorkflowStep",
            "name": "Configuration",
            "description": null,
            "arguments": {
                "alert_iri": "{{vars.input.params['alert_iri'] | ternary(vars.input.params['alert_iri'],vars.input.records[0]['@id'])}}",
                "malicious_indicator_weight": "20",
                "suspicious_indicator_weight": "10"
            },
            "status": null,
            "top": "165",
            "left": "125",
